INSERT INTO products (product_name, seller_id, step_price, start_price, current_price, buy_now_price, start_time, end_time, cat2_id, description, product_images, auto_extended)
VALUES ('Áo sơ mi nam công sở An Phước Cotton cao cấp', 2, 370000, 4490000, 4490000, NULL, '2026-08-20T08:09:29.735315', '2026-08-28T06:15:02.623989', 4, '<div class="product-auction-desc"><h3 class="text-xl font-bold text-gray-900 mb-3">Áo sơ mi nam công sở An Phước Cotton cao cấp</h3><p class="text-sm text-gray-700 leading-relaxed mb-4"><strong>Cam kết uy tín:</strong> Sản phẩm đấu giá chính hãng 100%, thông tin minh bạch, hình ảnh chụp thực tế rõ nét từng góc cạnh. Người bán cam kết chịu trách nhiệm cao nhất về chất lượng và xuất xứ sản phẩm.</p><h4 class="text-base font-semibold text-gray-800 border-b pb-1 mb-2">Thông số kỹ thuật & Chi tiết sản phẩm</h4><ul class="list-disc pl-5 text-sm text-gray-700 space-y-1 mb-4"><li><strong>Phân loại danh mục:</strong> Men''s Fashion</li><li><strong>Thương hiệu / Xuất xứ:</strong> An Phước - Việt Nam</li><li><strong>Quy cách / Cấu hình chi tiết:</strong> 100% Cotton Ai Cập chống nhăn, cổ đức lịch lãm</li><li><strong>Phiên bản / Kích thước:</strong> M, L, XL, XXL</li><li><strong>Tình trạng thực tế:</strong> Mới 100% Nguyên Hộp (Brand New) - Sản phẩm mới hoàn toàn chưa qua sử dụng, nguyên seal niêm phong của nhà sản xuất, đầy đủ hóa đơn chứng từ.</li></ul><h4 class="text-base font-semibold text-gray-800 border-b pb-1 mb-2">Quy định đấu giá, Giao hàng & Bảo hành</h4><ul class="list-disc pl-5 text-sm text-gray-700 space-y-1 mb-3"><li><strong>Chính sách bảo hành:</strong> Bảo hành trách nhiệm 12 tháng, đổi mới hoặc hoàn tiền 100% trong 15 ngày đầu nếu có bất kỳ lỗi kỹ thuật nào.</li><li><strong>Vận chuyển toàn quốc:</strong> Đóng gói bọc xốp chống sốc 3 lớp cẩn thận, có bảo hiểm hàng hóa, giao nhanh 2-4 ngày làm việc.</li><li><strong>Quyền lợi người mua:</strong> Quý khách được quyền mở hộp đồng kiểm tra hàng trước khi nhận và thanh toán.</li></ul><p class="text-xs text-gray-500 italic mt-3">Mọi thắc mắc về sản phẩm hoặc yêu cầu thêm hình ảnh chi tiết, quý khách vui lòng gửi câu hỏi tại mục Hỏi & Đáp bên dưới để được hỗ trợ nhanh chóng nhất.</p></div>', ARRAY['https://images.unsplash.com/photo-1548883354-7622d03aca27?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1550995694-3f5f4a7e1bd2?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1618354691373-d851c5c3a990?w=800&auto=format&fit=crop&q=80'], true);
INSERT INTO products (product_name, seller_id, step_price, start_price, current_price, buy_now_price, start_time, end_time, cat2_id, description, product_images, auto_extended)
VALUES ('Áo Polo nam Routine Form Regular thoáng khí', 3, 50000, 760000, 760000, NULL, '2026-08-03T16:31:44.788851', '2026-08-21T21:15:43.431411', 4, '<div class="product-auction-desc"><h3 class="text-xl font-bold text-gray-900 mb-3">Áo Polo nam Routine Form Regular thoáng khí</h3><p class="text-sm text-gray-700 leading-relaxed mb-4"><strong>Cam kết uy tín:</strong> Sản phẩm đấu giá chính hãng 100%, thông tin minh bạch, hình ảnh chụp thực tế rõ nét từng góc cạnh. Người bán cam kết chịu trách nhiệm cao nhất về chất lượng và xuất xứ sản phẩm.</p><h4 class="text-base font-semibold text-gray-800 border-b pb-1 mb-2">Thông số kỹ thuật & Chi tiết sản phẩm</h4><ul class="list-disc pl-5 text-sm text-gray-700 space-y-1 mb-4"><li><strong>Phân loại danh mục:</strong> Men''s Fashion</li><li><strong>Thương hiệu / Xuất xứ:</strong> Routine - Việt Nam</li><li><strong>Quy cách / Cấu hình chi tiết:</strong> Vải cá sấu Cotton Compact dệt tổ ong, co giãn 4 chiều</li><li><strong>Phiên bản / Kích thước:</strong> S, M, L, XL</li><li><strong>Tình trạng thực tế:</strong> Like New 99% Fullbox - Sản phẩm trưng bày hoặc dùng lướt vài lần trải nghiệm, ngoại hình hoàn hảo không vết xước, đầy đủ phụ kiện gốc và hộp.</li></ul><h4 class="text-base font-semibold text-gray-800 border-b pb-1 mb-2">Quy định đấu giá, Giao hàng & Bảo hành</h4><ul class="list-disc pl-5 text-sm text-gray-700 space-y-1 mb-3"><li><strong>Chính sách bảo hành:</strong> Bảo hành chính hãng toàn quốc 24 tháng theo số serial / IMEI, hỗ trợ kỹ thuật và chăm sóc trọn đời sản phẩm.</li><li><strong>Vận chuyển toàn quốc:</strong> Đóng gói bọc xốp chống sốc 3 lớp cẩn thận, có bảo hiểm hàng hóa, giao nhanh 2-4 ngày làm việc.</li><li><strong>Quyền lợi người mua:</strong> Quý khách được quyền mở hộp đồng kiểm tra hàng trước khi nhận và thanh toán.</li></ul><p class="text-xs text-gray-500 italic mt-3">Mọi thắc mắc về sản phẩm hoặc yêu cầu thêm hình ảnh chi tiết, quý khách vui lòng gửi câu hỏi tại mục Hỏi & Đáp bên dưới để được hỗ trợ nhanh